def localized_dinosaurs(lang):
    result = []
    for source in DINOSAURS:
        item = dict(source)
        for key, value in source.items():
            if isinstance(value, dict):
                item[key] = value[lang]
        item["dates_display"] = source["dates"] + " " + TEXT[lang]["date_suffix"]
        item["diet_kind"] = "plant" if "Plante" in source["diet"]["no"] or "Herbivore" in source["diet"]["en"] else "meat"
        filename, source_page, credit = PHOTOS[source["slug"]]
        from urllib.parse import quote
        item["image_url"] = "https://commons.wikimedia.org/wiki/Special:FilePath/" + quote(filename) + "?width=1400"
        item["image_source"] = "https://commons.wikimedia.org/wiki/File:" + quote(source_page.replace(" ", "_"), safe="()'!,")
        item["image_credit"] = credit
        result.append(item)
    return result


def localized_other_reptiles(kind, lang):
    result = []
    from urllib.parse import quote
    photo_fixes = {
        "mosasaurus": ("Mosasaurus hoffmannii - skeleton.jpg", "Ghedoghedo · CC BY-SA 3.0"),
        "plesiosaurus": ("Plesiosaurus dolichodeirus - MUSE.jpg", "Wikimedia Commons contributor"),
        "ichthyosaurus": ("Ichthyosaurus.jpg", "Tiia Monto · Wikimedia Commons"),
        "pteranodon": ("Pteranodon skeleton.JPG", "Wikimedia Commons contributor"),
        "quetzalcoatlus": ("Two Quetzalcoatlus.jpg", "TheUltimateGrass · CC0"),
    }
    for source in OTHER_REPTILES[kind]:
        item = dict(source)
        for key, value in source.items():
            if isinstance(value, dict):
                item[key] = value[lang]
        item["dates_display"] = source["dates"] + " " + TEXT[lang]["date_suffix"]
        item["diet_kind"] = "meat"
        filename, credit = photo_fixes[source["slug"]]
        item["image_url"] = "https://commons.wikimedia.org/wiki/Special:FilePath/" + quote(filename) + "?width=1400"
        item["image_source"] = "https://commons.wikimedia.org/wiki/File:" + quote(filename.replace(" ", "_"), safe="()'!,")
        item["image_credit"] = credit
        result.append(item)
    return result
